-- Migration: 20261129_catalogo_festivales_ficha.sql
-- Festivales de música de España (rock, indie, electrónica, punk, ska, reggae, folk, pop…) del directorio público
-- festivalesdeespana.com: nombre, ciudad, comunidad y la web que ENLAZA su ficha (url de la ficha en `fuente`).
-- No lleva emails (el directorio no guarda ninguno, ver server/utils/festivalesCatalogo.ts): el agente nocturno de emails
-- los busca en la web oficial de cada uno, con evidencia. Entran como «candidata»; cada banda los añade a su agenda.
-- Idempotente: una fila existente no se toca.

INSERT INTO catalogo_festivales (id, nombre, tipo_evento, ciudad, comunidad, pais, generos, web, estado_revision, fuente)
SELECT v.id, v.nombre, 'festival', NULLIF(v.ciudad, ''), NULLIF(v.comunidad, ''), 'ES', v.generos::text[], NULLIF(v.web, ''), 'candidata', v.ficha
